 @Override String amountUnit(String prefix){return prefix+" · "+(settings==null?"INR":settings.get("currency"));}
 @Override String ru(long value){if(settings==null)return super.ru(value);String currency=settings.get("currency"),grouping=settings.get("grouping"),digits=java.math.BigDecimal.valueOf(value,2).abs().setScale(2).toPlainString();String[] split=digits.split("\\.");String integer=split[0];if(!grouping.equals("None")){StringBuilder out=new StringBuilder();int n=0;for(int i=integer.length()-1;i>=0;i--){if(n>0&&(grouping.equals("Indian")?(n==3||(n>3&&(n-3)%2==0)):n%3==0))out.append(',');out.append(integer.charAt(i));n++;}integer=out.reverse().toString();}String prefix=currency+" ";if(settings.get("amountStyle").equals("Symbol")){switch(currency){case "INR":prefix="₹";break;case "USD":prefix="$";break;case "EUR":prefix="€";break;case "GBP":prefix="£";break;default:prefix=currency+" ";}}return (value<0?"−":"")+prefix+integer+"."+split[1];}
